@GetMapping("/events")
SseEmitter events() {
    SseEmitter emitter = new SseEmitter(30_000L);
    Executors.newSingleThreadExecutor().submit(() -> {
        try {
            for (int i = 1; i <= 3; i++) {
                emitter.send("tick " + i);
                Thread.sleep(500);
            }
            emitter.complete();
        } catch (Exception e) { emitter.completeWithError(e);
        }
    });
    return emitter;
}

