@PostMapping("/promote")
@ResponseBody
String promote(HttpServletRequest req) {
    HttpSession s = req.getSession(false);
    if (s == null) return "no session";
    String old = s.getId();
    String fresh = req.changeSessionId();       // same data, new id
    return (old.equals(fresh) ? "same" : "changed");
}

