    jdbc.update(con -> {
        PreparedStatement ps = con.prepareStatement(
            "insert into users(name, email) values (?, ?)",
            Statement.RETURN_GENERATED_KEYS);
        ps.setString(1, u.getName());
        ps.setString(2, u.getEmail());
        return ps;
    }, keys);
    return keys.getKey().longValue();
}

