            HttpServletResponse rs, FilterChain c)
            throws ServletException, IOException {
        long t = System.nanoTime();
        c.doFilter(rq, rs);
        System.out.println(rq.getRequestURI() + " "
            + (System.nanoTime() - t) / 1_000_000 + " ms");
    }
}

